                     "FEATURE_VOLCANIC_SOIL", "FEATURE_VOLCANO", "FEATURE_BURNING_FOREST",
                     "FEATURE_BURNT_FOREST", "FEATURE_BURNING_JUNGLE", "FEATURE_BURNT_JUNGLE"}
LAKE_MAX_TILES = 8  # enclosed water bodies (no ocean tile) up to this size are lakes


def resolve_path(p, bases=()):
    """Resolve a possibly-relative path. aip runs scripts with cwd = script folder,
    so also try the caller's $PWD and any extra bases."""
    if not p:
        return None
    cands = [p] if os.path.isabs(p) else (
        [os.path.join(b, p) for b in bases] + [os.path.join(os.environ.get("PWD", ""), p), p])
    for c in cands:
        if c and os.path.exists(c):
            return os.path.abspath(c)
    return None


def load_scenario(state):
    """Return (scenario dict, scenario path, map path). Accepts scenario_path
    (file or directory) and an optional map_path override."""
    sp = resolve_path(state.get("scenario_path"))
    if sp and os.path.isdir(sp):
        sp = os.path.join(sp, "scenario.json")
    if not sp or not os.path.isfile(sp):
        raise SystemExit(json.dumps({"error": f"scenario not found: {state.get('scenario_path')!r} "
                                              "(pass an absolute path)"}))
    with open(sp) as f:
        scen = json.load(f)
    d = os.path.dirname(sp)
    mp = resolve_path(state.get("map_path")) if state.get("map_path") else None
    if not mp:
        mf = scen.get("map_file") or scen.get("map") or ""
        # map_file is relative to the data root (e.g. "maps/x.Civ6Map" next to scenario_N/)
        mp = resolve_path(mf, bases=(d, os.path.dirname(d), os.path.dirname(os.path.dirname(d)),
                                     "/data", "/root/data", "/root"))
        if not mp and mf:
            base = os.path.basename(mf)
            for root in (os.path.dirname(d), "/data", "/root"):
                for r, _, files in os.walk(root) if os.path.isdir(root) else []:
                    if base in files:
                        mp = os.path.join(r, base)
                        break
                if mp:
                    break
    if not mp:
        raise SystemExit(json.dumps({"error": f"map file not found for {scen.get('map_file')!r}; "
                                              "set map_path in the state"}))
    return scen, sp, mp


def _q(cur, sql):
    try:
        return cur.execute(sql).fetchall()
    except sqlite3.OperationalError:
        return []  # table missing in this map


def classify_resource(rtype):
    name = (rtype or "").replace("RESOURCE_", "")
    if name in STRATEGIC:
        return "STRATEGIC"
    if name in BONUS:
        return "BONUS"
    if name in LUXURY:
        return "LUXURY"
    return None


def load_map(map_path):
    """Parse the .Civ6Map SQLite file. Returns dict with width, height, wrap_x,
    tiles {(x,y): Tile}, blocked {(x,y)} (ice / impassable non-mountain),
    start_positions, cities, districts, warnings, schema."""
    conn = sqlite3.connect(f"file:{map_path}?mode=ro", uri=True)
    cur = conn.cursor()
    tables = [r[0] for r in _q(cur, "SELECT name FROM sqlite_master WHERE type='table'")]
    m = _q(cur, "SELECT Width, Height, WrapX FROM Map LIMIT 1")
    plots = _q(cur, "SELECT ID, TerrainType, IsImpassable FROM Plots ORDER BY ID")
    if m:
        width, height, wrap_x = int(m[0][0]), int(m[0][1]), bool(m[0][2])
    else:  # no Map table: assume the duel-size default only if the plot count fits
        width, height, wrap_x = 44, max(1, len(plots) // 44), False
    warnings = []
    feats = dict(_q(cur, "SELECT ID, FeatureType FROM PlotFeatures"))
    res = {r[0]: r[1] for r in _q(cur, "SELECT ID, ResourceType FROM PlotResources") if r[1]}
    imps = {r[0]: r[1] for r in _q(cur, "SELECT ID, ImprovementType FROM PlotImprovements") if r[1]}
    rivers = _q(cur, "SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers")
    starts = _q(cur, "SELECT Plot, Type, Value FROM StartPositions")
    cities = _q(cur, "SELECT Owner, Plot, Name FROM Cities")
    dists = _q(cur, "SELECT DistrictType, CityID, Plot FROM Districts")
    conn.close()

    xy = lambda pid: (pid % width, pid // width)
    raw = {}
    blocked = set()
    unknown_terrain, unknown_res, wonders = set(), set(), set()
    for pid, ttype, impass in plots:
        x, y = xy(pid)
        t = (ttype or "").replace("TERRAIN_", "")
        is_hills = t.endswith("_HILLS")
        if t.endswith("_MOUNTAIN"):
            terrain = "MOUNTAIN"
        elif is_hills:
            terrain = t[:-6]
        else:
            terrain = t
        if terrain not in ("GRASS", "PLAINS", "DESERT", "TUNDRA", "SNOW", "COAST", "OCEAN", "MOUNTAIN"):
            unknown_terrain.add(ttype)
        feature = feats.get(pid)
        is_flood = False
        if feature and feature.startswith("FEATURE_FLOODPLAINS"):
            is_flood, feature = True, None
        elif feature and feature not in ORDINARY_FEATURES:
            wonders.add(feature)
            # civ6lib detects wonders by the substring "NATURAL_WONDER"; Campus matches
            # Great Barrier Reef by the substring "GREAT_BARRIER_REEF".
            core = feature.replace("FEATURE_", "")
            if core == "BARRIER_REEF":
                core = "GREAT_BARRIER_REEF"
            feature = "NATURAL_WONDER_" + core
        rtype = res.get(pid)
        rclass = classify_resource(rtype)
        if rtype and rclass is None:
            unknown_res.add(rtype)
            rclass = "LUXURY"  # unknown: treat as unbuildable (conservative)
        imp = imps.get(pid)
        if imp:
            imp = imp.replace("IMPROVEMENT_", "")
        raw[(x, y)] = dict(x=x, y=y, terrain=terrain, feature=feature, is_hills=is_hills,
                           is_floodplains=is_flood, river_edges=set(),
                           resource=(rtype.replace("RESOURCE_", "") if rtype else None),
                           resource_type=rclass, improvement=imp)
        if feature == "FEATURE_ICE" or (impass and terrain != "MOUNTAIN"):
            blocked.add((x, y))

    for pid, ne, w, nw in rivers:
        x, y = xy(pid)
        for flag, d in ((w, 0), (nw, 1), (ne, 2)):
            if flag:
                raw[(x, y)]["river_edges"].add(d)
                n = get_neighbor_at_direction(x, y, d)
                if n in raw:
                    raw[n]["river_edges"].add((d + 3) % 6)

    # Lakes: enclosed water bodies with no ocean tile and <= LAKE_MAX_TILES tiles.
    seen = set()
    for c, r in raw.items():
        if c in seen or r["terrain"] not in ("COAST", "OCEAN"):
            continue
        body, dq = [], deque([c])
        seen.add(c)
        while dq:
            cur_c = dq.popleft()
            body.append(cur_c)
            for n in get_neighbors(*cur_c):
                if n in raw and n not in seen and raw[n]["terrain"] in ("COAST", "OCEAN"):
                    seen.add(n)
                    dq.append(n)
        if len(body) <= LAKE_MAX_TILES and all(raw[b]["terrain"] == "COAST" for b in body):
            for b in body:
                raw[b]["terrain"] = "LAKE"

    tiles = {}
    for c, r in raw.items():
        r["river_edges"] = sorted(r["river_edges"])
        tiles[c] = Tile(**r)

    if unknown_terrain:
        warnings.append(f"unrecognized terrain types (kept as-is): {sorted(unknown_terrain)}")
    if unknown_res:
        warnings.append(f"unrecognized resources treated as LUXURY (unbuildable): {sorted(unknown_res)}")
    if wonders:
        warnings.append(f"natural wonder features found: {sorted(wonders)}")
    if wrap_x:
        land_x = [c[0] for c, t in tiles.items() if not t.is_water]
        if land_x and (min(land_x) <= 3 or max(land_x) >= width - 4):
            warnings.append("map wraps on X and land lies within 3 tiles of the seam; "
                            "civ6lib hex math does not wrap, so seam adjacency is ignored")

    return dict(width=width, height=height, wrap_x=wrap_x, tiles=tiles, blocked=blocked,
                tables=tables,
                start_positions=[{"plot": p, "xy": list(xy(p)), "type": t, "value": v}
                                 for p, t, v in starts],
                cities=[{"owner": o, "plot": p, "xy": list(xy(p)), "name": n} for o, p, n in cities],
                districts=[{"type": t, "city_id": c, "plot": p, "xy": list(xy(p))}
                           for t, c, p in dists],
                warnings=warnings)


def read_stdin():
    data = sys.stdin.read()
    payload = json.loads(data) if data.strip() else {}
    return payload.get("currentState", payload)

input.content:
"""Step `optimize`: choose city center(s) and district placements that maximize
total adjacency bonus, then validate and score the result with civ6lib verbatim.

stdin currentState keys used:
  scenario_path (str), map_path (str, optional), district_pool (str:
  specialty_only | with_infrastructure | all), center_mode (str: free |
  start_position | existing_city | given), fixed_city_centers (list of [x, y],
  only for center_mode=given), time_limit_s (number, optional, default 240).
stdout: {"solution": {...}, "total_adjacency": int, "solution_valid": bool}

Search (map-optimization-strategy): prune tiles with civ6lib PlacementRules,
score (type, tile) pairs, then branch-and-bound over district types per
candidate center, seeded by a greedy solution. The fast scorer is built from
civ6lib's own per-neighbor rule matching, and the final answer is re-scored
with AdjacencyCalculator.calculate_total_adjacency, so reported numbers are
civ6lib's numbers.
"""

import json
import sys
import time

from civ6map import load_map, load_scenario, read_stdin

from adjacency_rules import (AdjacencyCalculator, DISTRICT_ADJACENCY_RULES,  # noqa: E402
                             DISTRICTS_FOR_ADJACENCY)
from hex_utils import get_neighbors, get_tiles_in_range, hex_distance  # noqa: E402
from placement_rules import (DistrictType as DT, PlacementRules,  # noqa: E402
                             calculate_max_specialty_districts, validate_city_distances,
                             validate_district_count, validate_district_uniqueness)

SPECIALTY = [DT.CAMPUS, DT.HOLY_SITE, DT.THEATER_SQUARE, DT.COMMERCIAL_HUB, DT.HARBOR,
             DT.INDUSTRIAL_ZONE, DT.GOVERNMENT_PLAZA, DT.ENTERTAINMENT_COMPLEX, DT.WATER_PARK,
             DT.DIPLOMATIC_QUARTER, DT.ENCAMPMENT, DT.AERODROME, DT.PRESERVE]
INFRA = [DT.AQUEDUCT, DT.DAM, DT.CANAL]
EXTRA = [DT.NEIGHBORHOOD, DT.SPACEPORT]
POOLS = {"specialty_only": SPECIALTY, "with_infrastructure": SPECIALTY + INFRA,
         "all": SPECIALTY + INFRA + EXTRA}
ONE_PER_CIV = {DT.GOVERNMENT_PLAZA, DT.DIPLOMATIC_QUARTER}


class Scorer:
    """Exact re-implementation of AdjacencyCalculator totals, decomposed per
    neighbor. Each (rule, neighbor, district-on-neighbor) match is computed by
    civ6lib's count_rule_sources on a one-tile map and cached."""

    def __init__(self, tiles):
        self.tiles = tiles
        self.calc = AdjacencyCalculator(tiles)
        self.rules = {t: list(r) for t, r in DISTRICT_ADJACENCY_RULES.items()}
        self._nm = {}
        self._destroyed = {}

    def destroyed(self, n, t):
        key = (n, t)
        if key not in self._destroyed:
            mini = AdjacencyCalculator({n: self.tiles[n]})
            self._destroyed[key] = mini.apply_destruction({n: t})[n]
        return self._destroyed[key]

    def nm(self, rule, d, n, ptype):
        """1 if neighbor n (holding ptype or nothing) matches `rule` for a district at d."""
        key = (id(rule), n, ptype)
        v = self._nm.get(key)
        if v is None:
            if n not in self.tiles:
                v = 0
            else:
                tile = self.tiles[n] if ptype is None else self.destroyed(n, ptype)
                v, _ = self.calc.count_rule_sources(d[0], d[1], rule, {n: tile},
                                                    {n: ptype} if ptype is not None else {})
            self._nm[key] = v
        return v

    def district_score(self, c, t, P):
        rules = self.rules.get(t)
        if not rules:
            return 0
        s = 2 if (t == DT.COMMERCIAL_HUB and self.tiles[c].has_river) else 0
        nbrs = get_neighbors(*c)
        for r in rules:
            cnt = 0
            for n in nbrs:
                cnt += self.nm(r, c, n, P.get(n))
            s += cnt * r.bonus_per if r.count_required == 1 else (cnt // r.count_required) * r.bonus_per
        return s

    def total(self, P):
        return sum(self.district_score(c, t, P) for c, t in P.items() if t != DT.CITY_CENTER)


def valid_center(tile, c, blocked, occupied):
    return (tile is not None and not tile.is_water and not tile.is_mountain
            and not tile.is_natural_wonder and c not in blocked and c not in occupied)


def optimize_city(sc, tiles, blocked, center, fixed, pool, k, deadline, best_global):
    """Branch-and-bound for one city. fixed: {coord: DT} already on the map
    (this city's center included). Returns (score, placements {coord: DT}, exact)."""
    rules_obj = PlacementRules(tiles, center, 0)
    in_range = [c for c in get_tiles_in_range(center[0], center[1], 3)
                if c in tiles and c not in blocked and c not in fixed]
    cand = {}
    for t in pool:
        cs = [c for c in in_range if rules_obj.validate_placement(t, c[0], c[1], fixed).valid]
        if cs:
            cand[t] = cs
    types = list(cand)
    if not types:
        return sc.total(fixed), {}, True
    base = sc.total(fixed)
    n_spec_types = sum(1 for t in types if t not in INFRA + EXTRA)
    d_max = min(k, n_spec_types) + sum(1 for t in types if t in INFRA + EXTRA)

    # Which pool types can sit on each tile (for neighbor-gain bounds).
    on_tile = {}
    for t, cs in cand.items():
        for c in cs:
            on_tile.setdefault(c, []).append(t)

    def self_ub(t, c):
        rules = sc.rules.get(t)
        if not rules:
            return 0
        s = 2 if (t == DT.COMMERCIAL_HUB and tiles[c].has_river) else 0
        for r in rules:
            cnt, gains = 0, []
            for n in get_neighbors(*c):
                if n in fixed:
                    cnt += sc.nm(r, c, n, fixed[n])
                    continue
                v0 = sc.nm(r, c, n, None)
                vb = max([sc.nm(r, c, n, u) for u in on_tile.get(n, []) if u != t] or [0])
                cnt += v0
                if vb > v0:
                    gains.append(vb - v0)
            cnt += sum(sorted(gains, reverse=True)[:max(0, d_max - 1)])
            s += cnt * r.bonus_per if r.count_required == 1 else (cnt // r.count_required) * r.bonus_per
        return s

    sub = {t: max(self_ub(t, c) for c in cand[t]) for t in types}
    # inc[x][d]: most a district of type x can add to an adjacent district of type d.
    inc = {}
    for x in types:
        inc[x] = {}
        for d, rules in sc.rules.items():
            tot = 0
            for r in rules:
                hit = any(s == x.name or (s == "DISTRICT" and x in DISTRICTS_FOR_ADJACENCY)
                          for s in r.sources)
                tot += r.bonus_per if hit else 0
            inc[x][d] = tot

    # Static value of each (type, tile) alone, for move ordering.
    static = {t: sorted(cand[t], key=lambda c: -(sc.total({**fixed, c: t}) - base)) for t in types}
    order = sorted(types, key=lambda t: -sub[t])

    def key(score, P):
        ns = sum(1 for t in P.values() if t not in INFRA + EXTRA)
        return (score, -len(P) + ns, -ns)  # fewer districts at equal score

    # Greedy seed: add the best marginal (type, tile) while it helps.
    P, used_t, spec = {}, set(), 0
    cur = base
    while True:
        best_mv = None
        for t in types:
            if t in used_t or (t not in INFRA + EXTRA and spec >= k):
                continue
            for c in cand[t]:
                if c in P:
                    continue
                v = sc.total({**fixed, **P, c: t})
                if v > cur and (best_mv is None or v > best_mv[0]):
                    best_mv = (v, t, c)
        if not best_mv:
            break
        cur, t, c = best_mv
        P[c] = t
        used_t.add(t)
        spec += t not in INFRA + EXTRA
    best = [cur, dict(P)]
    floor_score = max(best_global, cur)
    exact = [True]
    nodes = [0]

    def ub_rest(i, P, spec):
        placed_scoring = [t for t in P.values() if t in sc.rules] + \
                         [t for c, t in fixed.items() if t in sc.rules and hex_distance(*c, *center) <= 4]
        spec_vals, free_vals = [], []
        for t in order[i:]:
            g = sub[t] + sum(sorted((inc[t][d] for d in placed_scoring), reverse=True)[:6])
            if g <= 0:
                continue
            (free_vals if t in INFRA + EXTRA else spec_vals).append(g)
        spec_vals.sort(reverse=True)
        return sum(spec_vals[:max(0, k - spec)]) + sum(free_vals)

    def dfs(i, P, spec):
        nodes[0] += 1
        if nodes[0] % 2048 == 0 and time.time() > deadline:
            exact[0] = False
            raise TimeoutError
        cur_total = sc.total({**fixed, **P})
        if cur_total > best[0]:
            best[0], best[1] = cur_total, dict(P)
        if i == len(order):
            return
        if cur_total + ub_rest(i, P, spec) <= max(best[0], floor_score):
            return
        t = order[i]
        is_free = t in INFRA + EXTRA
        if is_free or spec < k:
            for c in static[t]:
                if c in P:
                    continue
                P[c] = t
                dfs(i + 1, P, spec + (0 if is_free else 1))
                del P[c]
        dfs(i + 1, P, spec)

    try:
        dfs(0, {}, 0)
    except TimeoutError:
        pass

    # Fill unused specialty slots with districts that do not lower the total.
    P = dict(best[1])
    score = best[0]
    spec = sum(1 for t in P.values() if t not in INFRA + EXTRA)
    while spec < k:
        mv = None
        for t in types:
            if t in INFRA + EXTRA or t in P.values():
                continue
            for c in cand[t]:
                if c in P:
                    continue
                v = sc.total({**fixed, **P, c: t})
                if v >= score and (mv is None or v > mv[0]):
                    mv = (v, t, c)
        if not mv:
            break
        score, t, c = mv
        P[c] = t
        spec += 1
    return score, P, exact[0], nodes[0]


def main():
    state = read_stdin()
    t0 = time.time()
    scen, sp, mp = load_scenario(state)
    m = load_map(mp)
    tiles, blocked = m["tiles"], m["blocked"]
    pop = int(scen.get("population", state.get("population", 1)) or 1)
    ncities = int(scen.get("num_cities", 1) or 1)
    k = calculate_max_specialty_districts(pop)
    pool_name = state.get("district_pool") or "with_infrastructure"
    if pool_name not in POOLS:
        raise SystemExit(json.dumps({"error": f"district_pool must be one of {list(POOLS)}"}))
    mode = state.get("center_mode") or "free"
    limit = float(state.get("time_limit_s") or 240)
    deadline = t0 + limit
    sc = Scorer(tiles)

    # Pre-existing districts on the map stay where they are and count as neighbors.
    fixed = {}
    for d in m["districts"]:
        name = d["type"].replace("DISTRICT_", "")
        if name in DT.__members__:
            fixed[tuple(d["xy"])] = DT[name]

    if mode == "given":
        forced = [tuple(c) for c in (state.get("fixed_city_centers") or [])]
        if not forced:
            raise SystemExit(json.dumps({"error": "center_mode=given needs fixed_city_centers [[x,y],...]"}))
    elif mode == "start_position":
        sps = sorted(m["start_positions"], key=lambda s: str(s["value"]))
        forced = [tuple(s["xy"]) for s in sps]
    elif mode == "existing_city":
        forced = [tuple(c["xy"]) for c in m["cities"]]
    else:
        forced = []
    start_xy = {tuple(s["xy"]) for s in m["start_positions"]}

    cities = []
    notes = []
    used_civ = set()
    all_exact = True
    total_nodes = 0
    for ci in range(ncities):
        pool = [t for t in POOLS[pool_name] if t not in used_civ]
        if ci < len(forced):
            centers = [forced[ci]]
        else:
            if forced and mode != "free":
                notes.append(f"only {len(forced)} centers available for mode {mode}; "
                             f"choosing city {ci + 1} freely")
            centers = [c for c, t in tiles.items()
                       if valid_center(t, c, blocked, fixed)
                       and validate_city_distances([cc["center"] for cc in cities] + [c], tiles)[0]]
        best = None
        per_center = []
        for center in sorted(centers, key=lambda c: (c not in start_xy, c[1], c[0])):
            if time.time() > deadline and best is not None:
                all_exact = False
                notes.append("time limit reached; remaining centers skipped")
                break
            f = {**fixed, center: DT.CITY_CENTER}
            city_deadline = max(deadline, time.time() + 5) if best is None else deadline
            score, P, exact, nodes = optimize_city(sc, tiles, blocked, center, f, pool, k,
                                                   city_deadline, best[0] if best else -1)
            total_nodes += nodes
            all_exact &= exact
            per_center.append((score, center))
            nspec = sum(1 for t in P.values() if t not in INFRA + EXTRA)
            cand_key = (score, nspec, -len(P), center in start_xy)
            if best is None or cand_key > best[3]:
                best = (score, center, P, cand_key)
        if best is None:
            notes.append(f"no valid city center for city {ci + 1}")
            break
        score, center, P, _ = best
        fixed = {**fixed, center: DT.CITY_CENTER, **P}
        used_civ |= {t for t in P.values() if t in ONE_PER_CIV}
        per_center.sort(key=lambda x: (-x[0], x[1][1], x[1][0]))
        cities.append({"center": center, "placements": P,
                       "top_centers": [{"city_center": list(c), "total": s} for s, c in per_center[:5]]})

    # Re-score and validate everything with civ6lib verbatim.
    calc = AdjacencyCalculator(tiles)
    total, per = calc.calculate_total_adjacency(fixed)
    errors = []
    out_cities = []
    all_named = {}
    for i, city in enumerate(cities):
        rules_obj = PlacementRules(tiles, city["center"], pop)
        named = {}
        for c, t in city["placements"].items():
            others = {cc: tt for cc, tt in fixed.items() if cc != c}
            res = rules_obj.validate_placement(t, c[0], c[1], others)
            if not res.valid:
                errors.extend(f"{t.name}@{c}: {e}" for e in res.errors)
            named[t.name] = list(c)
        ok, errs = validate_district_count({n: tuple(v) for n, v in named.items()}, pop)
        errors += errs
        ok, errs = validate_district_uniqueness({n: tuple(v) for n, v in named.items()}, f"city_{i + 1}")
        errors += errs
        all_named[f"city_{i + 1}"] = {n: tuple(v) for n, v in named.items()}
        adj = {t.name: per[f"{t.name}@({c[0]},{c[1]})"].total_bonus
               for c, t in city["placements"].items() if f"{t.name}@({c[0]},{c[1]})" in per}
