},
{
"$ref": "#/$defs/RouterStep"
},
{
"$ref": "#/$defs/EndStep"
}
]
},
"minItems": 2,
"title": "Steps",
"type": "array"
},
"anti_patterns": {
"description": "Common mistakes the procedure steers the agent away from. Concrete corrections to errors the agent would otherwise make.",
"items": {
"type": "string"
},
"title": "Anti Patterns",
"type": "array"
}
},
"required": [
"purpose",
"trigger_when",
"steps"
],
"type

