def valid_center(tile, c, blocked, occupied):
    return (tile is not None and not tile.is_water and not tile.is_mountain
            and not tile.is_natural_wonder and c not in blocked and c not in occupied)


def optimize_city(sc, tiles, blocked, center, fixed, pool, k, deadline, best_global):
    """Branch-and-bound for one city. fixed: {coord: DT} already on the map
    (this city's center included). Returns (score, placements {coord: DT}, exact)."""
    rules_obj = PlacementRules(tiles, center, 0)
    in_range = [c for c in get_tiles_in_range(center[0], center[1], 3)
                if c in tiles and c not in blocked and c not in fixed]
    cand = {}
    for t in pool:
        cs = [c for c in in_range if rules_obj.validate_placement(t, c[0], c[1], fixed).valid]
        if cs:
            cand[t] = cs
    # Dominance: Diplomatic Quarter is valid wherever Encampment/Aerodrome/Preserve
    # are and contributes the same (a +0.5 district, no own adjacency), so those
    # three never beat it.
    if DT.DIPLOMATIC_QUARTER in cand:
        for t in (DT.ENCAMPMENT, DT.AERODROME, DT.PRESERVE):
            cand.pop(t, None)
    types = list(cand)
    if not types:
        return sc.total(fixed), {}, True, 0
    base = sc.total(fixed)
    n_spec_types = sum(1 for t in types if t not in INFRA + EXTRA)
    d_max = min(k, n_spec_types) + sum(1 for t in types if t in INFRA + EXTRA)

    # Which pool types can sit on each tile (for neighbor-gain bounds).
    on_tile = {}
    for t, cs in cand.items():
        for c in cs:
            on_tile.setdefault(c, []).append(t)

    def rule_cap(r, t):
        """How many neighbors can gain a match for rule r from districts still to place:
        any district for "DISTRICT", otherwise one per matching type (one of each)."""
        if "DISTRICT" in r.sources:
            return max(0, d_max - 1)
        return sum(1 for u in types if u != t and u.name in r.sources)

    def self_ub(t, c):
        rules = sc.rules.get(t)
        if not rules:
            return 0
        s = 2 if (t == DT.COMMERCIAL_HUB and tiles[c].has_river) else 0
        for r in rules:
            cnt, gains = 0, []
            for n in get_neighbors(*c):
                if n in fixed:
                    cnt += sc.nm(r, c, n, fixed[n])
                    continue
                v0 = sc.nm(r, c, n, None)
                vb = max([sc.nm(r, c, n, u) for u in on_tile.get(n, []) if u != t] or [0])
                cnt += v0
                if vb > v0:
                    gains.append(vb - v0)
            cnt += sum(sorted(gains, reverse=True)[:rule_cap(r, t)])
            s += cnt * r.bonus_per if r.count_required == 1 else (cnt // r.count_required) * r.bonus_per
        return s

    sub = {t: max(self_ub(t, c) for c in cand[t]) for t in types}
    # inc[x][d]: most a district of type x can add to an adjacent district of type d.
    inc = {}
    for x in types:
        inc[x] = {}
        for d, rules in sc.rules.items():
            tot = 0
            for r in rules:
                hit = any(s == x.name or (s == "DISTRICT" and x in DISTRICTS_FOR_ADJACENCY)
                          for s in r.sources)
                tot += r.bonus_per if hit else 0
            inc[x][d] = tot

    # Static value of each (type, tile) alone, for move ordering.
    static = {t: sorted(cand[t], key=lambda c: -(sc.total({**fixed, c: t}) - base)) for t in types}
    order = sorted(types, key=lambda t: -sub[t])

    # Tiles a district of type x could touch (for the gain-to-placed bound).
    reach = {x: {n for c in cand[x] for n in get_neighbors(*c)} for x in types}

    # Greedy seed: add the best marginal (type, tile) while it helps.
    P, used_t, spec = {}, set(), 0
    cur = base
    while True:
        best_mv = None
        for t in types:
            if t in used_t or (t not in INFRA + EXTRA and spec >= k):
                continue
            for c in cand[t]:
                if c in P:
                    continue
                v = sc.total({**fixed, **P, c: t})
                if v > cur and (best_mv is None or v > best_mv[0]):
                    best_mv = (v, t, c)
        if not best_mv:
            break
        cur, t, c = best_mv
        P[c] = t
        used_t.add(t)
        spec += t not in INFRA + EXTRA
    best = [cur, dict(P)]
    floor_score = max(best_global, cur)
    exact = [True]
    nodes = [0]

    near_fixed = [(c, t) for c, t in fixed.items() if t in sc.rules and hex_distance(*c, *center) <= 4]

    def ub_rest(i, P, spec):
        placed = [(c, t) for c, t in P.items() if t in sc.rules] + near_fixed
        spec_vals, free_vals = [], []
        for t in order[i:]:
            g = sub[t] + sum(sorted((inc[t][d] for c, d in placed if c in reach[t]), reverse=True)[:6])
            if g <= 0:
                continue
            (free_vals if t in INFRA + EXTRA else spec_vals).append(g)
        spec_vals.sort(reverse=True)
        return sum(spec_vals[:max(0, k - spec)]) + sum(free_vals)

    tile_ub = {t: {c: self_ub(t, c) for c in cand[t]} for t in types}
    by_ub = {t: sorted(cand[t], key=lambda c: (-tile_ub[t][c], static[t].index(c))) for t in types}
    A = dict(fixed)  # every placement on the map during the search

    def local(c):
        """Score of c and its scoring neighbors under A."""
        tot = 0
        for d in [c] + get_neighbors(*c):
            t = A.get(d)
            if t is not None and t in sc.rules:
                tot += sc.district_score(d, t, A)
        return tot

    def dfs(i, P, spec, cur_total):
        nodes[0] += 1
        if nodes[0] % 2048 == 0 and time.time() > deadline:
            exact[0] = False
            raise TimeoutError
        if cur_total > best[0]:
            best[0], best[1] = cur_total, dict(P)
        if i == len(order):
            return
        target = max(best[0], floor_score)
        if cur_total + ub_rest(i, P, spec) <= target:
            return
        t = order[i]
        is_free = t in INFRA + EXTRA
        spec2 = spec + (0 if is_free else 1)
        if is_free or spec < k:
            for c in by_ub[t]:
                if c in A:
                    continue
                give = sum(inc[t][A[n]] for n in get_neighbors(*c) if A.get(n) in sc.rules)
                if cur_total + tile_ub[t][c] + give + ub_rest(i + 1, P, spec2) <= max(best[0], floor_score):
                    continue
                before = local(c)
                A[c] = t
                P[c] = t
                child = cur_total + local(c) - before
                dfs(i + 1, P, spec2, child)
                del A[c]
                del P[c]
        dfs(i + 1, P, spec, cur_total)

    try:
        dfs(0, {}, 0, base)
    except TimeoutError:
        pass

    # Fill unused specialty slots with districts that do not lower the total.
    P = dict(best[1])
    score = best[0]
    spec = sum(1 for t in P.values() if t not in INFRA + EXTRA)
    while spec < k:
        mv = None
        for t in types:
            if t in INFRA + EXTRA or t in P.values():
                continue
            for c in cand[t]:
                if c in P:
                    continue
                v = sc.total({**fixed, **P, c: t})
                if v >= score and (mv is None or v > mv[0]):
                    mv = (v, t, c)
        if not mv:
            break
        score, t, c = mv
        P[c] = t
        spec += 1
    return score, P, exact[0], nodes[0]


def main():
    state = read_stdin()
    t0 = time.time()
    scen, sp, mp = load_scenario(state)
    m = load_map(mp)
    tiles, blocked = m["tiles"], m["blocked"]
    pop = int(scen.get("population", state.get("population", 1)) or 1)
    ncities = int(scen.get("num_cities", 1) or 1)
    k = calculate_max_specialty_districts(pop)
    pool_name = state.get("district_pool") or "with_infrastructure"
    if pool_name not in POOLS:
        raise SystemExit(json.dumps({"error": f"district_pool must be one of {list(POOLS)}"}))
    allowed = state.get("allowed_districts") or []
    if allowed:  # an explicit list from the task overrides the pool
        names = {str(a).strip().upper().replace(" ", "_").replace("DISTRICT_", "") for a in allowed}
        unknown = sorted(n for n in names if n not in DT.__members__)
        if unknown:
            raise SystemExit(json.dumps({"error": f"unknown district names in allowed_districts: {unknown}"}))
        POOLS["custom"] = [t for t in POOLS["all"] if t.name in names]
        pool_name = "custom"
    mode = state.get("center_mode") or "free"
    limit = float(state.get("time_limit_s") or 240)

