        is_free = t in INFRA + EXTRA
        spec2 = spec + (0 if is_free else 1)
        if is_free or spec < self.k:
            A, sc, inc = self.A, self.sc, self.inc[t]
            rest = self.ub_rest(i + 1, P, spec2)
            for c in self.by_ub[t]:
